export function parseKeyValueArgs(args) {
  const out = {};
  for (const arg of args) {
    if (!arg.startsWith('--')) continue;
    const eq = arg.indexOf('=');
    if (eq === -1) continue;
    const key = arg.slice(2, eq);
    out[key] = arg.slice(eq + 1);
  }
  return out;
}

