export function loadConfig(env) {
  const port = typeof env.PORT === 'string' && /^\d+$/.test(env.PORT) ? Number(env.PORT) : 3000;
  let debug = false;
  if (typeof env.DEBUG === 'string') {
    const lower = env.DEBUG.toLowerCase();
    if (lower === 'true' || lower === '1') debug = true;
  }
  const name = typeof env.APP_NAME === 'string' && env.APP_NAME.length > 0 ? env.APP_NAME : 'app';
  return { port, debug, name };
}

