bootforge/node-core/runtime/paths-and-ur.solution:
function segments(p) {
  return p.split('/').filter((seg) => seg.length > 0);
}

export function routeMatch(pattern, pathname) {
  const patParts = segments(pattern);
  const pathParts = segments(pathname);
  if (patParts.length !== pathParts.length) return null;
  const params = {};
  for (let i = 0; i < patParts.length; i++) {
    const pat = patParts[i];
    if (pat.startsWith(':')) {
      params[pat.slice(1)] = pathParts[i];
    } else if (pat !== pathParts[i]) {
      return null;
    }
  }
  return params;
}

