export function truncateToBytes(s, maxBytes) {
  let used = 0;
  let out = '';
  for (const ch of s) {
    const cost = Buffer.byteLength(ch, 'utf8');
    if (used + cost > maxBytes) break;
    used += cost;
    out += ch;
  }
  return out;
}

