export function createEventLog() {
  const listeners = new Map();
  const log = [];
  return {
    on(name, fn) {
      if (!listeners.has(name)) listeners.set(name, []);
      listeners.get(name).push(fn);
    },
    emit(name, payload) {
      log.push({ name, payload });
      const fns = listeners.get(name) ?? [];
      for (const fn of fns) {
        fn(payload);
      }
      return fns.length > 0;
    },
    history() {
      return log.map((entry) => ({ name: entry.name, payload: entry.payload }));
    },
    replay(fn) {
      for (const entry of log) {
        fn(entry.name, entry.payload);
      }
    },
  };
}

