import { EventEmitter } from 'node:events';

export function removeOne(labels, removeLabel) {
  const emitter = new EventEmitter();
  const log = [];
  const fns = new Map();
  for (const label of labels) {
    const fn = () => log.push(label);
    fns.set(label, fn);
    emitter.on('run', fn);
  }
  if (fns.has(removeLabel)) {
    emitter.off('run', fns.get(removeLabel));
  }
  emitter.emit('run');
  return log;
}

