export function createFullBus() {
  // combine: Map of named listeners, wildcard array, once-wrappers, snapshot iteration
}

bootforge/node-core/runtime/events/typed.solution:
export function createFullBus() {
  const listeners = new Map();
  const anyListeners = [];

  function removeNamed(name, fn) {
    const fns = listeners.get(name);
    if (!fns) return;
    const i = fns.indexOf(fn);
    if (i !== -1) fns.splice(i, 1);
  }

  function addNamed(name, fn) {
    if (!listeners.has(name)) listeners.set(name, []);
    listeners.get(name).push(fn);
    return () => removeNamed(name, fn);
  }

  return {
    on(name, fn) {
      return addNamed(name, fn);
    },
    once(name, fn) {
      const wrapper = (payload) => {
        removeNamed(name, wrapper);
        fn(payload);
      };
      return addNamed(name, wrapper);
    },
    onAny(fn) {
      anyListeners.push(fn);
      return () => {
        const i = anyListeners.indexOf(fn);
        if (i !== -1) anyListeners.splice(i, 1);
      };
    },
    emit(name, payload) {
      let invoked = 0;
      const named = [...(listeners.get(name) ?? [])];
      for (const fn of named) {
        fn(payload);
        invoked++;
      }
      for (const fn of [...anyListeners]) {
        fn(name, payload);
        invoked++;
      }
      return invoked;
    },
    listenerCount(name) {
      return (listeners.get(name) ?? []).length;
    },
  };
}

