import { createHash } from 'node:crypto';

function shardFor(key, n) {
  const hex = createHash('sha256').update(key).digest('hex').slice(0, 8);
  return parseInt(hex, 16) % n;
}

export function distribute(keys, n) {
  const out = {};
  for (const key of keys) {
    const shard = shardFor(key, n);
    if (!out[shard]) out[shard] = [];
    out[shard].push(key);
  }
  return out;
}

