export function integrityCheck(files) {
  const valid = [];
  const corrupted = [];
  for (const file of files) {
    const digest = createHash('sha256').update(file.content).digest('hex');
    if (digest === file.expectedHash) {
      valid.push(file.name);
    } else {
      corrupted.push(file.name);
    }
  }
  return { valid, corrupted };
}

