export function setPath(obj, path, value) {
  // recursive: copy this level, recurse for the rest of the path
}

bootforge/node-core/node-patterns/json-c.solution:
export function setPath(obj, path, value) {
  const keys = path.split('.');
  function assign(current, index) {
    const key = keys[index];
    const base = current !== null && typeof current === 'object' && !Array.isArray(current) ? current : {};
    if (index === keys.length - 1) {
      return { ...base, [key]: value };
    }
    return { ...base, [key]: assign(base[key], index + 1) };
  }
  return assign(obj, 0);
}

