bootforge/node-core/node-patterns/json-c.solution:
export function diffConfig(oldConfig, newConfig) {
  const changed = [];
  const added = [];
  const removed = [];
  for (const key of Object.keys(oldConfig)) {
    if (!Object.hasOwn(newConfig, key)) removed.push(key);
    else if (newConfig[key] !== oldConfig[key]) changed.push(key);
  }
  for (const key of Object.keys(newConfig)) {
    if (!Object.hasOwn(oldConfig, key)) added.push(key);
  }
  return { changed: changed.sort(), added: added.sort(), removed: removed.sort() };
}

