}

bootforge/node-core/node-patterns/stream.solution:
export function createChunkBuffer(size) {
  let buffer = '';
  return {
    feed(s) {
      buffer += s;
      const blocks = [];
      while (buffer.length >= size) {
        blocks.push(buffer.slice(0, size));
        buffer = buffer.slice(size);
      }
      return blocks;
    },
    flush() {
      const rest = buffer;
      buffer = '';
      return rest;
    },
  };
}

