export function createBufferedWriter(highWaterMark) {
  let buffer = '';
  return {
    write(s) {
      buffer += s;
      return buffer.length < highWaterMark;
    },
    buffered() {
      return buffer.length;
    },
    drain() {
      const flushed = buffer;
      buffer = '';
      return flushed;
    },
  };
}

