export function createLineSplitter() {
  // buffer partial lines between pushes; strip \r before \n
}

bootforge/node-core/node-patterns/stream.solution:
export function createLineSplitter() {
  let buffer = '';
  return {
    push(piece) {
      buffer += piece;
      const lines = [];
      let nl = buffer.indexOf('\n');
      while (nl !== -1) {
        let line = buffer.slice(0, nl);
        if (line.endsWith('\r')) {
          line = line.slice(0, -1);
        }
        lines.push(line);
        buffer = buffer.slice(nl + 1);
        nl = buffer.indexOf('\n');
      }
      return lines;
    },
    flush() {
      const rest = buffer;
      buffer = '';
      return rest;
    },
  };
}

